import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const B=JSON.parse('{"title":"NACT Framing","description":"","frontmatter":{},"headers":[],"relativePath":"transport/nact/framing.md","filePath":"transport/nact/framing.md","lastUpdated":1791613576000}'),r={name:"transport/nact/framing.md"};function c(s,t,h,i,n,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="nact-framing" tabindex="-1">NACT Framing <a class="header-anchor" href="#nact-framing" aria-label="Permalink to &quot;NACT Framing&quot;">​</a></h1><p>NACT 会把一个 NACP 包分片成一个或多个 NACT 帧。</p><p>无论是否需要分片，每一帧NACT都会额外添加长度为 32 Bytes 的帧头。</p><h2 id="nact-帧头" tabindex="-1">NACT 帧头 <a class="header-anchor" href="#nact-帧头" aria-label="Permalink to &quot;NACT 帧头&quot;">​</a></h2><div style="overflow-x:auto;"><table style="display:table;overflow:visible;min-width:960px;table-layout:fixed;text-align:center;"><thead><tr><th style="width:72px;">Offset</th><th>+0</th><th>+1</th><th>+2</th><th>+3</th><th>+4</th><th>+5</th><th>+6</th><th>+7</th><th>+8</th><th>+9</th><th>+A</th><th>+B</th><th>+C</th><th>+D</th><th>+E</th><th>+F</th></tr></thead><tbody><tr><th><code>0x00</code></th><td colspan="16"><code>msgId</code><br>16 B</td></tr><tr><th><code>0x10</code></th><td colspan="4"><code>offset</code><br>4 B</td><td colspan="4"><code>totalSize</code><br>4 B</td><td colspan="4"><code>thisFrameSize</code><br>4 B</td><td colspan="2"><code>blank</code><br>2 B</td><td><code>magic</code><br>1 B</td><td><code>version</code><br>1 B</td></tr></tbody></table></div><p>帧体紧跟在 32B 帧头后，从 <code>0x20</code> 开始，长度为 <code>thisFrameSize - 32</code>。</p><table tabindex="0"><thead><tr><th>Offset</th><th>长度</th><th>字段</th><th>编码</th><th>v1 值</th><th>含义</th></tr></thead><tbody><tr><td>0</td><td>16</td><td><code>msgId</code></td><td>16 bytes</td><td>-</td><td>同一 <strong>NACP 包</strong>的所有帧相同</td></tr><tr><td>16</td><td>4</td><td><code>offset</code></td><td>uint32, BE</td><td>—</td><td>本帧在所属 NACP 包中的起始字节</td></tr><tr><td>20</td><td>4</td><td><code>totalSize</code></td><td>uint32, BE</td><td>—</td><td>所属 NACP 包的总长度</td></tr><tr><td>24</td><td>4</td><td><code>thisFrameSize</code></td><td>uint32, BE</td><td>—</td><td><strong>本帧总长，含这 32B 帧头</strong>，故 <code>bodyLen = thisFrameSize - 32</code>。</td></tr><tr><td>28</td><td>2</td><td><code>blank</code></td><td>uint16, BE</td><td><code>0x0000</code></td><td>预留给未来的指示位</td></tr><tr><td>30</td><td>1</td><td><code>magic</code></td><td>uint8</td><td><code>0xCF</code></td><td>魔数</td></tr><tr><td>31</td><td>1</td><td><code>version</code></td><td>uint8</td><td><code>0x01</code></td><td>NACT Message版本</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong>feat: NACT对单帧和单包的大小限制分别为2GB和4GB</strong></p><p>由于<code>totalSize</code>长度仅4Bytes，因此最大的长度只有2^(4*8)-1 Bytes，即约4GB。</p><p>这个数字其实是原先Node20对Buffer的最大限制，尽管在Node24中上限被提高到了8PB。</p><p>此外 <code>thisFrameSize</code> 超过 <code>MAX_FRAME_SIZE</code>（默认 2 GiB）则会出现 <code>frame-too-large</code>错误。</p><p>本特性在 <strong>（NASDK v1.0.4，NACT v1）</strong> 仍存在。未来可能会通过增加头部长度、缩短msgID或利用Blank字段提升长度限制。<s>但是至少最近一段时间不会考虑修改NACT</s></p></div><h2 id="分帧与重组" tabindex="-1">分帧与重组 <a class="header-anchor" href="#分帧与重组" aria-label="Permalink to &quot;分帧与重组&quot;">​</a></h2><p>NACP 包超过分片阈值时，NACT 会把它分片成多个帧依次发送。</p><p>分片阈值来自 <code>TransportSpec.nact.chunkSize</code>，省略时使用当前 Provider 声明的推荐默认值。</p><p>分片的目的是为了穿透物理传输中间层的单次提交上限（如部分CDN限制100MB上传之类的），同时进一步降低发送端合并产生的内存峰值。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>NACP默认分片大小是100MB，但UnixSocket默认不分片。</p></div><details class="details custom-block"><summary>Details</summary><p>1GB payload 实测：</p><table tabindex="0"><thead><tr><th>provider</th><th>分帧</th><th>wire (ms)</th><th>接收端内存峰值</th></tr></thead><tbody><tr><td>unix</td><td>一帧</td><td>665</td><td>1024 MB</td></tr><tr><td>unix</td><td>100MB × 11</td><td>668</td><td>1024 MB</td></tr><tr><td>tcp</td><td>一帧</td><td>734</td><td>1024 MB</td></tr><tr><td>tcp</td><td>100MB × 11</td><td>667</td><td>1024 MB</td></tr><tr><td>ws</td><td>一帧</td><td>2784</td><td>3027 MB</td></tr><tr><td>ws</td><td>100MB × 11</td><td>3931</td><td><strong>1147 MB</strong></td></tr></tbody></table><p>Q：这里为什么会x11</p><p>A：因为这一组测试把 <code>chunkSize</code> 设为 100MB，NACT 保证<strong>加上帧头后每一帧不超过 100MB</strong>，所以每帧只装 <code>100MB-32B</code> 的数据，余下的 <code>320B</code> 单独成一帧（<code>32B</code> 帧头 + <code>320B</code>）。</p></details>',14)])])}const m=d(r,[["render",c]]);export{B as __pageData,m as default};
